def download_for_property(property_id):
    body = {
        "propertyRequest": {
            "startDate": f"01/1/{YEAR}",
            "endDate": f"12/1/{YEAR}",
            "geographyIds": [property_id],
            "intervalCode": "MQ",
            "geographyMetrics": METRICS,
            "geographyNiches": [{"category":"All","niche":"All"}],
            "propertyAttributes": ATTRIBUTES,
            "repivotBy": "kpi"
        }
    }

    response = requests.post(
        "https://dac.realpage.com/mac/dd/download/excel/conventional",
        headers=HEADERS,
        json=body
    )

    if response.status_code == 200:
        folder = os.path.expanduser(f"C:\\Users\\patel\\Desktop\\Personal\\work\\Realpage\\property_data\\{YEAR}")
        os.makedirs(folder, exist_ok=True)
        filename = f"property_{property_id}_{YEAR}"
        file_path = os.path.join(folder, f"{filename}")
        content_type = response.headers.get("Content-Type", "")
        if content_type in ["application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",  "application/vnd.ms-excel"]:
            with open(f"{file_path}.xls" if content_type == "application/vnd.ms-excel" else f"{file_path}.xlsx", "wb") as f:
                f.write(response.content)
            print(f"✅ Downloaded {filename}")
        else:
            print(f"Unexpected content type: {content_type}")
    else:
        print(f"❌ Failed for property_id {property_id} - Status: {response.status_code}, Message: {response.text}")
        exit()
